CSS="""*{box-sizing:border-box}body{margin:0;background:#0d1320;color:#eef4fc;font:1rem/1.55 system-ui,sans-serif}main{max-width:1120px;margin:auto;padding:24px}h1,h2{line-height:1.2;overflow-wrap:anywhere}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,280px),1fr));gap:16px}fieldset{margin:0 0 16px;border:1px solid #61728a;border-radius:14px;padding:16px;min-width:0}legend{font-weight:700}.fields{display:grid;gap:10px}.field{display:grid;gap:4px;min-width:0}input:not([type=checkbox]),select{width:100%;min-width:0;padding:10px;color:inherit;background:#152338;border:1px solid #8192aa;border-radius:8px;font:inherit}input[aria-invalid=true]{border:2px solid #f8aa96}.toggle{display:flex;gap:8px;align-items:flex-start}.toggle input{width:20px;height:20px;flex:none;accent-color:#39e1c6}button{padding:10px 16px;margin:8px 8px 12px 0;background:#18364a;color:inherit;border:1px solid #8192aa;border-radius:8px;font:inherit;cursor:pointer}button:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid #39e1c6;outline-offset:3px}.result{border-top:1px solid #61728a;padding-top:8px;margin-top:12px;overflow-wrap:anywhere}.result p{margin:4px 0}small{display:block;color:#b8c8da}"""
JS="""(()=>{"use strict";const t=JSON.parse(document.getElementById('copy').textContent);const g=id=>document.getElementById(id);const cards=[...document.querySelectorAll('[data-option]')];function amount(el){const s=el.value;const blank=s===''&&!el.validity.badInput;const n=Number(s);const valid=/^[0-9]+$/.test(s)&&Number.isSafeInteger(n)&&n>=0&&n<=1000000000;el.setAttribute('aria-invalid',String(!blank&&!valid));return blank?{state:'unknown'}:valid?{state:'known',n}:{state:'invalid'};}function render(){const budget=amount(g('budget')),desired=g('wanted').value;let count=0;for(const c of cards){const i=c.dataset.option;const v=k=>g(k+i);const rent=amount(v('rent')),term=v('term').value;const filled=Boolean(v('alias').value.trim()||v('area').value.trim()||rent.state!=='unknown'||term!=='unknown'||v('source').checked);const keep=v('keep');keep.disabled=!filled;if(!filled)keep.checked=false;if(keep.checked)count++;let bs='unknown',ts='unknown';if(rent.state==='invalid'||budget.state==='invalid')bs='invalid';else if(rent.state==='known'&&budget.state==='known')bs=rent.n<=budget.n?'fit':'miss';if(desired==='any')ts='any';else if(term!=='unknown')ts=term===desired?'fit':'miss';v('budgetResult').textContent=({fit:t.budgetFit,miss:t.budgetMiss,unknown:t.budgetUnknown,invalid:t.invalid})[bs];v('termResult').textContent=({fit:t.termFit,miss:t.termMiss,unknown:t.termUnknown,any:t.termAny})[ts];v('sourceResult').textContent=v('source').checked?t.checked:t.unchecked;v('summary').textContent=!filled?t.empty:bs==='invalid'?t.invalid:bs==='miss'||ts==='miss'?t.mismatch:bs==='fit'&&(ts==='fit'||ts==='any')?t.matched:t.incomplete;}g('count').textContent=t.count+' '+count+' / 3';}document.querySelectorAll('input,select').forEach(x=>{x.addEventListener('input',render);x.addEventListener('change',render);});function clear(){document.querySelectorAll('input').forEach(x=>{if(x.type==='checkbox')x.checked=false;else x.value='';});g('wanted').value='any';cards.forEach(c=>g('term'+c.dataset.option).value='unknown');}g('example').addEventListener('click',()=>{clear();g('budget').value='40000';g('wanted').value='6';g('alias1').value='A — DEMO';g('rent1').value='35000';g('term1').value='6';g('alias2').value='B — DEMO';g('rent2').value='30000';g('term2').value='12';render();});g('reset').addEventListener('click',()=>{clear();render();g('budget').focus();});render();})();"""
def pin(s):return base64.b64encode(hashlib.sha256(s.encode()).digest()).decode()
def render(l):
 c=COPY[l];e=lambda v:html.escape(v,quote=True)
 def opts(keys):return "".join(f'<option value="{k}">{e(c[label])}</option>' for k,label in keys)
 def field(id,label,kind,extra=""):return f'<label class="field" for="{id}"><span>{e(label)}</span><input id="{id}" type="{kind}" {extra}></label>'
 num='inputmode="numeric" min="0" max="1000000000" step="1" autocomplete="off"'
 cards=[]
 for i in range(1,4):
  cards.append(f'<fieldset data-option="{i}"><legend>{e(c["option"])} {i}</legend><div class="fields">'+field(f"alias{i}",c["alias"],"text",'maxlength="50" autocomplete="off"')+field(f"area{i}",c["area"],"text",'maxlength="50" autocomplete="off"')+field(f"rent{i}",c["rent"],"number",num)+f'<label class="field" for="term{i}"><span>{e(c["term"])}</span><select id="term{i}">'+opts([("unknown","unknown"),("6","six"),("12","twelve"),("other","other")])+f'</select></label><label class="toggle"><input id="source{i}" type="checkbox">{e(c["source"])}</label><label class="toggle"><input id="keep{i}" type="checkbox" disabled>{e(c["keep"])}</label></div><div class="result" aria-live="polite"><strong id="summary{i}">{e(c["empty"])}</strong><p id="budgetResult{i}"></p><p id="termResult{i}"></p><p id="sourceResult{i}"></p></div></fieldset>')
 data=json.dumps(c,ensure_ascii=False).replace("<","\\u003c")
 policy=f"default-src 'none'; script-src 'sha256-{pin(JS)}'; style-src 'sha256-{pin(CSS)}'; connect-src 'none'; form-action 'none'; base-uri 'none'; object-src 'none'"
 return (f'<!doctype html><html lang="{l}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><meta http-equiv="Content-Security-Policy" content="{e(policy)}"><title>{e(c["title"])}</title><style>{CSS}</style></head><body><main><h1>{e(c["title"])}</h1><p>{e(c["intro"])}</p><fieldset><legend>THB</legend><div class="grid">'+field("budget",c["budget"],"number",num)+f'<label class="field" for="wanted"><span>{e(c["wanted"])}</span><select id="wanted">'+opts([("any","any"),("6","six"),("12","twelve")])+f'</select></label></div><button id="example" type="button">{e(c["example"])}</button><button id="reset" type="button">{e(c["reset"])}</button></fieldset><p id="count" role="status">{e(c["count"])} 0 / 3</p><div class="grid">'+''.join(cards)+f'</div><small>{e(c["privacy"])}</small></main><script id="copy" type="application/json">{data}</script><script>{JS}</script></body></html>\n').encode()
def build(manifest):
 if hashlib.sha256(manifest).hexdigest()!=MANIFEST_SHA:raise ValueError("parent manifest drift")
 return {l+"/rental-shortlist.html":render(l) for l in COPY}
def main():
 p=argparse.ArgumentParser(description=__doc__);p.add_argument("--repo",required=True,type=Path);p.add_argument("--output",required=True,type=Path);a=p.parse_args()
 repo=a.repo.resolve();out=a.output.resolve();git=lambda *args:subprocess.check_output(["git","-C",str(repo),*args])
 if git("rev-parse",BASE+"^{commit}").decode().strip()!=BASE:raise ValueError("Git baseline")
 if out==repo or repo in out.parents or out.exists():raise ValueError("new output outside repository required")
 pages=build(git("show",BASE+":deploy/live/_release.json"))
 out.mkdir(parents=True,exist_ok=False)
 for name,b in pages.items():
  f=out/name;f.parent.mkdir(parents=True,exist_ok=True);f.write_bytes(b)
if __name__=="__main__":main()
